def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70

    supply = day_context['supply']
    day = day_context['day']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # Baseline: if we are in danger, bid high but not necessarily max.
    if my_status['hp'] is not None and my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # Read immediate opponent behavior from yesterday.
    highest_prev_bid = None
    any_prev = False
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid')
            any_prev = True
            if highest_prev_bid is None or bid > highest_prev_bid:
                highest_prev_bid = bid

    # Supply-aware scaling: in this scenario supply is between 15 and 25.
    # If supply is closer to our requirement, we should bid more.
    try:
        supply_ratio = float(supply) / float(WATER_REQ)
    except Exception:
        supply_ratio = 1.0

    # Target bid levels.
    # If opponents were aggressive yesterday, slightly undercut to avoid getting dragged into high bids.
    if any_prev and highest_prev_bid is not None:
        aggressive = highest_prev_bid >= DAILY_SALARY * 0.85
        if aggressive:
            # If our hp is decent, defend with a medium-high bid.
            if my_status.get('hp', 0) is not None and my_status['hp'] >= 4:
                target = DAILY_SALARY * 0.35 + (highest_prev_bid * 0.15)
            else:
                target = DAILY_SALARY * 0.55 + (highest_prev_bid * 0.2)
        else:
            # Opponents were not too aggressive; bid to secure water.
            target = max(DAILY_SALARY * 0.5, (highest_prev_bid + 2.0))
    else:
        # No trace info: moderate bid.
        target = DAILY_SALARY * 0.55

    # Adjust for supply tightness.
    # If supply_ratio < 1.2, water is tighter => bid higher.
    if supply_ratio < 1.2:
        target *= 1.15
    elif supply_ratio > 1.6:
        target *= 0.95

    # If we have many no-water days, we must prioritize.
    no_water_days = my_status.get('no_water_days', 0)
    if no_water_days is not None and no_water_days >= 2:
        target *= 1.2

    # Clamp to budget and a sensible upper bound.
    budget = my_status.get('budget', 0)
    if budget is None:
        budget = 0

    # Never exceed budget.
    bid = min(budget, target)

    # Ensure non-negative.
    if bid < 0:
        bid = 0

    return bid

