            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= DAILY_SALARY * 0.8:
                    aggressive_count += 1
            if prev.get('error'):
                desperate_count += 1

    players = 1 + len(alive_opponents)
    expected_share = supply / max(players, 1)
    scarcity = expected_share < WATER_REQ

    if hp <= 2 or no_water >= 2:
        bid = DAILY_SALARY * 0.98
    elif hp <= 4 or no_water >= 1:
        bid = DAILY_SALARY * 0.82 if scarcity else DAILY_SALARY * 0.68
    else:
        if scarcity:
            bid = DAILY_SALARY * 0.62
        else:
            bid = DAILY_SALARY * 0.42

    if prev_bids:
        top_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        if top_prev >= DAILY_SALARY * 0.9:
            if hp > 4 and no_water == 0:
                bid = min(bid, DAILY_SALARY * 0.38)
            else:
                bid = max(bid, DAILY_SALARY * 0.88)
        elif scarcity:
            bid = max(bid, min(DAILY_SALARY * 0.86, top_prev + 2.0))
        else:
            bid = max(bid, min(DAILY_SALARY * 0.6, avg_prev + 1.0))

    if desperate_count >= max(1, len(alive_opponents) // 2) and hp > 4 and no_water == 0:
        bid *= 0.9

    if day >= 8:
        if hp <= 4 or no_water >= 1:
            bid = max(bid, DAILY_SALARY * 0.9)
        else:
            bid = max(bid, DAILY_SALARY * 0.5)

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

