    MY_DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_agents = len(alive_opponents) + 1 # including myself

    # 1. Look at yesterday's situation (Trace)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Default bid based on my urgency
    base_bid = MY_DAILY_SALARY * 0.5 # Moderate default

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        # Critical state: Bid very high
        base_bid = MY_DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        # Moderately critical state
        base_bid = MY_DAILY_SALARY * 0.7
    else:
        # Healthy state: Can be more conservative
        base_bid = MY_DAILY_SALARY * 0.4

    # 2. Adjust based on opponent's previous bids
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= MY_DAILY_SALARY * 0.8: # Opponent bid very high yesterday
            if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
                base_bid = max(base_bid, highest_prev_bid + 5) # Must outbid if desperate
            else:
                base_bid = max(base_bid, MY_DAILY_SALARY * 0.6) # Be competitive if healthy
        elif highest_prev_bid >= MY_DAILY_SALARY * 0.5: # Opponent bid moderately high yesterday
            if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
                base_bid = max(base_bid, highest_prev_bid + 2) # Ensure win if urgent
            else:
                base_bid = max(base_bid, MY_DAILY_SALARY * 0.55) # Stay slightly above to win
        else: # Opponent bid low yesterday
            if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
                base_bid = max(base_bid, highest_prev_bid + 10) # Ensure win, but don't overpay too much
            else:
                base_bid = min(base_bid, highest_prev_bid + 1) # Try to win cheaply

    # 3. Adjust based on current supply vs total demand
    current_supply = day_context['supply']
    total_water_demand_all = MY_WATER_REQUIREMENT + sum(o['water_requirement'] for o in alive_opponents)

    if current_supply < total_water_demand_all:
        # Water is scarce, increase bid aggressiveness
        if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
            base_bid = max(base_bid, MY_DAILY_SALARY * 0.98) # Push even higher if desperate
        else:
            base_bid = max(base_bid, MY_DAILY_SALARY * 0.75) # Be aggressive even if healthy
    elif current_supply >= total_water_demand_all + (num_alive_agents * MY_WATER_REQUIREMENT * 0.5): # Abundant supply
        # Water is very abundant, can be less aggressive
        if my_status['hp'] > 3 and my_status['no_water_days'] == 0:
            base_bid = min(base_bid, MY_DAILY_SALARY * 0.25) # Save money if healthy
        else:
            base_bid = min(base_bid, MY_DAILY_SALARY * 0.4) # Still moderate but lower if not fully healthy

    # Final bid must be within budget and non-negative
    final_bid = max(0, min(my_status['budget'], base_bid))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
