def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])  # ensure integer
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.3)

    # Collect yesterday's bids
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid: enough to secure water if needed
    if hp <= 2 or no_water_days >= 1:
        urgency_factor = 0.9
    elif hp <= 4:
        urgency_factor = 0.7
    else:
        urgency_factor = 0.5

    base_bid = DAILY_SALARY * urgency_factor

    # Adjust based on yesterday's competition
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If yesterday was fierce, maybe conserve
        if max_prev >= DAILY_SALARY * 0.8:
            if hp > 3:
                base_bid = DAILY_SALARY * 0.4
            else:
                base_bid = DAILY_SALARY * 0.9
        else:
            # Slightly edge above highest if we need water
            if hp <= 4:
                base_bid = max(base_bid, max_prev + 2)
            else:
                base_bid = min(base_bid, max_prev - 1)

    # Supply factor: lower supply increases competition, so bid higher
    supply_ratio = supply / 20.0
    supply_adjust = (1.0 - supply_ratio) * 20  # range 0 to 10
    base_bid += supply_adjust

    # Clamp to budget
    bid = min(budget, max(1, base_bid))
    return int(bid)  # ensure integer return
